const supplierExistsByNumber = `-- name: SupplierExistsByNumber :one
SELECT COUNT(*) > 0 AS supplier_exists FROM account_relation
WHERE owner_account_id = ?
AND external_number = ?
AND account_relation_role_code = 'supplier'
AND (? IS NULL OR counterparty_account_id != ?)
`

type SupplierExistsByNumberParams struct {
	OwnerAccountID        string
	ExternalNumber        string
	ExcludeCounterpartyID sql.NullString
}

func (q *Queries) SupplierExistsByNumber(ctx context.Context, arg SupplierExistsByNumberParams) (bool, error) {
	row := q.db.QueryRowContext(ctx, supplierExistsByNumber,
		arg.OwnerAccountID,
		arg.ExternalNumber,
		arg.ExcludeCounterpartyID,
		arg.ExcludeCounterpartyID,
	)
	var supplier_exists bool
	err := row.Scan(&supplier_exists)
	return supplier_exists, err
}

